import { TestBed } from '@angular/core/testing';
import { HttpClientTestingModule, HttpTestingController } from '@angular/common/http/testing';
import { MatDialog } from '@angular/material/dialog';
import { of } from 'rxjs';
import { HashInterceptor } from './hash-interceptor.interceptor';
import { BcAlertComponent } from 'src/app/shared/components/bc-alert/bc-alert.component';

describe('HashInterceptor', () => {
  let interceptor: HashInterceptor;
  let dialogService: jest.Mocked<MatDialog>;
  let httpMock: HttpTestingController;

  beforeEach(() => {
    const dialogSpy = {
      open: jest.fn()
    };

    TestBed.configureTestingModule({
      imports: [HttpClientTestingModule],
      providers: [
        HashInterceptor,
        { provide: MatDialog, useValue: dialogSpy }
      ]
    });

    interceptor = TestBed.inject(HashInterceptor);
    dialogService = TestBed.inject(MatDialog) as jest.Mocked<MatDialog>;
    httpMock = TestBed.inject(HttpTestingController);
  });

  afterEach(() => {
    httpMock.verify();
  });

  it('should show an alert with the correct message', () => {
    const message = 'Test error message';
    const dialogRefSpyObj = { afterClosed: jest.fn().mockReturnValue(of({})), close: jest.fn() };
    dialogService.open.mockReturnValue(dialogRefSpyObj as any);

    interceptor.showAlert(message);

    expect(dialogService.open).toHaveBeenCalledWith(BcAlertComponent, {
      type: 'error',
      text: message,
      timeout: 60000,
    });
  });
});
